command:
$ErrorActionPreference = 'Continue'
# #997 MIGRATION — MIG-07. Continue MIG-06 backwards. Every release from v0.18.0 to v0.32.15 ships
# cudart 12.8 (file version ...12080), which driver 560.94 / CUDA 12.6 cannot load. Find the boundary
# where the shipped CUDA runtime drops to something this driver accepts -- or establish that no
# published native Ollama does, which is itself the answer and has to be said plainly rather than
# guessed at.
#
# The tag list is deliberately wide and old. A 404 on a tag that never existed costs one failed curl.

$tmp = 'D:\HermesServices\ollama\_probe'
Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path $tmp | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem

Write-Output '--- ALL-TAGS-OLDEST-FIRST ---'
try {
    $all = @()
    foreach ($page in 1..4) {
        $r = Invoke-WebRequest -Uri "https://api.github.com/repos/ollama/ollama/releases?per_page=100&page=$page" -UseBasicParsing -TimeoutSec 60
        $all += ($r.Content | ConvertFrom-Json)
    }
    $sorted = $all | Sort-Object published_at
    Write-Output "total=$($all.Count) oldest=$($sorted[0].tag_name)@$($sorted[0].published_at) newest=$($sorted[-1].tag_name)@$($sorted[-1].published_at)"
    $sorted | Where-Object { -not $_.prerelease } | Select-Object -First 90 | ForEach-Object {
        $z = $_.assets | Where-Object { $_.name -eq 'ollama-windows-amd64.zip' }
        "OLD $($_.tag_name) published=$($_.published_at) zip_bytes=$(if ($z) { $z.size } else { 'NO_STANDALONE_ZIP' })"
    }
} catch { Write-Output "releases_ERR=$($_.Exception.Message)" }

foreach ($tag in @('v0.17.1', 'v0.16.0', 'v0.15.0', 'v0.14.0', 'v0.13.0', 'v0.12.0', 'v0.11.0', 'v0.10.0', 'v0.9.0')) {
    Write-Output "=== $tag ==="
    $zip = Join-Path $tmp "probe.zip"
    Remove-Item $zip -Force -ErrorAction SilentlyContinue
    try {
        $url = "https://github.com/ollama/ollama/releases/download/$tag/ollama-windows-amd64.zip"
        & curl.exe -L --fail --silent --show-error -o $zip $url 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0 -or -not (Test-Path $zip)) { Write-Output "  no_such_asset rc=$LASTEXITCODE"; continue }
        Write-Output "  zip_bytes=$((Get-Item $zip).Length)"
        $za = [System.IO.Compression.ZipFile]::OpenRead($zip)
        $dirs = $za.Entries | ForEach-Object { $_.FullName } | Where-Object { $_ -match '^lib/ollama/[^/]+/' } |
            ForEach-Object { ($_ -split '/')[2] } | Sort-Object -Unique
        Write-Output "  runner_dirs=$($dirs -join ',')"
        foreach ($e in ($za.Entries | Where-Object { $_.Name -match '^cudart64.*\.dll$' })) {
            $dest = Join-Path $tmp 'x.dll'
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, $dest, $true)
            Write-Output "  dll=$($e.FullName) file_version=$((Get-Item $dest).VersionInfo.FileVersion)"
            Remove-Item $dest -Force
        }
        $za.Dispose()
    } catch { Write-Output "  ERR=$($_.Exception.Message)" }
    finally { Remove-Item $zip -Force -ErrorAction SilentlyContinue }
}
Remove-Item -Recurse -Force $tmp -ErrorAction SilentlyContinue
Write-Output '--- RC ---'

